struct ModelConfig {
        name string
        max_context int
        max_output int
        req_per_min int
        tokens_per_min int
        req_per_hour int
        tokens_per_hour int
        req_per_day int
        tokens_per_day int
        temperature f64
        top_p f64
}

struct Message {
        role string
        content string
}

struct CompletionRequest {
        model string @[json: model]
        messages []Message @[json: messages]
        stream bool @[json: stream]
        max_completion_tokens int @[json: max_completion_tokens]
        temperature f64 @[json: temperature]
        top_p f64 @[json: top_p]
}

struct DeltaMessage {
        content string @[json: content]
}

struct StreamChoice {
        index int @[json: index]
        delta DeltaMessage @[json: delta]
}

struct StreamChunk {
        choices []StreamChoice @[json: choices]
}

struct JAIDETrainingExample {
        instruction string @[json: instruction]
        input string @[json: input]
        output string @[json: output]
        metadata JAIDEMetadata @[json: metadata]
}

struct JAIDEMetadata {
        source_url string @[json: source_url]
        timestamp i64 @[json: timestamp]
        content_type string @[json: content_type]
        token_count int @[json: token_count]
