fn new_rate_limiter(model_name string, config ModelConfig) &RateLimiter {
        now := time.now().unix()
        return &RateLimiter{
                mtx: sync.new_mutex()
                model_name: model_name
                config: config
                minute_reset_time: now + 60
                hour_reset_time: now + 3600
                day_reset_time: now + 86400
        }
}

fn (mut rl RateLimiter) check_and_wait(estimated_tokens int) ! {
        rl.mtx.@lock()
        defer {
                rl.mtx.unlock()
        }
        now := time.now().unix()
        if now >= rl.minute_reset_time {
                rl.requests_this_minute = 0
                rl.tokens_this_minute = 0
                rl.minute_reset_time = now + 60
        }
        if now >= rl.hour_reset_time {
                rl.requests_this_hour = 0
                rl.tokens_this_hour = 0
                rl.hour_reset_time = now + 3600
        }
        if now >= rl.day_reset_time {
                rl.requests_this_day = 0
                rl.tokens_this_day = 0
                rl.day_reset_time = now + 86400
        }
        for rl.requests_this_minute >= rl.config.req_per_min - 1 {
                wait_time := rl.minute_reset_time - time.now().unix()
                if wait_time > 0 {
                        rl.mtx.unlock()
                        time.sleep(wait_time * time.second)
                        rl.mtx.@lock()
                }
                rl.requests_this_minute = 0
                rl.tokens_this_minute = 0
                rl.minute_reset_time = time.now().unix() + 60
        }
        for rl.tokens_this_minute + estimated_tokens > rl.config.tokens_per_min {
                wait_time := rl.minute_reset_time - time.now().unix()
                if wait_time > 0 {
                        rl.mtx.unlock()
                        time.sleep(wait_time * time.second)
                        rl.mtx.@lock()
                }
                rl.tokens_this_minute = 0
                rl.minute_reset_time = time.now().unix() + 60
        }
        if rl.requests_this_hour >= rl.config.req_per_hour {
                return error('Hourly request limit reached for ${rl.model_name}')
        }
        if rl.requests_this_day >= rl.config.req_per_day {
                return error('Daily request limit reached for ${rl.model_name}')
        }
        rl.requests_this_minute++
        rl.requests_this_hour++
        rl.requests_this_day++
        rl.tokens_this_minute += estimated_tokens
        rl.tokens_this_hour += estimated_tokens
        rl.tokens_this_day += estimated_tokens
}

fn clean_html_tags(text string) string {
        mut result := text
        result = result.replace('<', ' <')
        result = result.replace('>', '> ')
        mut in_tag := false
        mut cleaned := strings.new_builder(result.len)
        for ch in result {
                if ch == `<` {
                        in_tag = true
                        continue
                }
                if ch == `>` {
                        in_tag = false
                        continue
                }
                if !in_tag {
                        cleaned.write_u8(ch)
                }
        }
        mut final_text := cleaned.str()
        final_text = final_text.replace('&nbsp;', ' ')
        final_text = final_text.replace('&amp;', '&')
        final_text = final_text.replace('&lt;', '<')
        final_text = final_text.replace('&gt;', '>')
        final_text = final_text.replace('&quot;', '"')
        final_text = final_text.replace('&#39;', "'")
        final_text = final_text.replace('&#8217;', "'")
        final_text = final_text.replace('&#8220;', '"')
        final_text = final_text.replace('&#8221;', '"')
        final_text = final_text.replace('&#8211;', '-')
        final_text = final_text.replace('&#8212;', '-')
        final_text = final_text.replace('  ', ' ')
        final_text = final_text.replace('   ', ' ')
        final_text = final_text.replace('    ', ' ')
        return final_text.trim_space()
}

fn extract_between(text string, start_marker string, end_marker string) string {
        start_idx := text.index(start_marker) or { return '' }
        after_start := text[start_idx + start_marker.len..]
        end_idx := after_start.index(end_marker) or { return after_start }
        return after_start[..end_idx]
}

fn extract_all_between(text string, start_marker string, end_marker string) []string {
        mut results := []string{}
        mut search_text := text
        for {
                start_idx := search_text.index(start_marker) or { break }
                after_start := search_text[start_idx + start_marker.len..]
                end_idx := after_start.index(end_marker) or { break }
                results << after_start[..end_idx]
                search_text = after_start[end_idx + end_marker.len..]
        }
        return results
}

fn extract_scientific_content(html string) string {
        mut content := strings.new_builder(4096)
        title := extract_between(html, '<h1 class="title mathjax">', '</h1>')
        if title.len > 0 {
                clean_title := clean_html_tags(title)
                if clean_title.len > 0 {
                        if clean_title.starts_with('Title:') {
                                content.write_string(clean_title[6..].trim_space())
                        } else {
                                content.write_string('Title: ')
                                content.write_string(clean_title)
                        }
                        content.write_string('\n\n')
                }
        }
        authors := extract_between(html, '<div class="authors">', '</div>')
        if authors.len > 0 {
                clean_authors := clean_html_tags(authors)
                if clean_authors.len > 0 {
                        content.write_string('Authors: ')
                        content.write_string(clean_authors)
                        content.write_string('\n\n')
                }
        }
        abstract := extract_between(html, '<blockquote class="abstract mathjax">', '</blockquote>')
        if abstract.len > 0 {
                clean_abstract := clean_html_tags(abstract)
                if clean_abstract.starts_with('Abstract:') {
                        clean_abstract = clean_abstract[9..].trim_space()
                }
                if clean_abstract.len > 0 {
                        content.write_string('Abstract: ')
                        content.write_string(clean_abstract)
                        content.write_string('\n\n')
                }
        }
        comments := extract_between(html, '<td class="tablecell comments mathjax">', '</td>')
        if comments.len > 0 {
                clean_comments := clean_html_tags(comments)
                if clean_comments.len > 10 {
                        content.write_string('Comments: ')
                        content.write_string(clean_comments)
                        content.write_string('\n\n')
                }
        }
        subjects := extract_between(html, '<td class="tablecell subjects">', '</td>')
        if subjects.len > 0 {
                clean_subjects := clean_html_tags(subjects)
                if clean_subjects.len > 0 {
                        content.write_string('Subjects: ')
                        content.write_string(clean_subjects)
                        content.write_string('\n\n')
                }
        }
        doi := extract_between(html, '<td class="tablecell doi">', '</td>')
        if doi.len > 0 {
                clean_doi := clean_html_tags(doi)
                if clean_doi.len > 5 {
                        content.write_string('DOI: ')
                        content.write_string(clean_doi)
                        content.write_string('\n\n')
                }
        }
        journal_ref := extract_between(html, '<td class="tablecell jref">', '</td>')
        if journal_ref.len > 0 {
                clean_jref := clean_html_tags(journal_ref)
                if clean_jref.len > 5 {
                        content.write_string('Journal Reference: ')
                        content.write_string(clean_jref)
                        content.write_string('\n\n')
                }
        }
        return content.str().trim_space()
}

fn extract_arxiv_id(url string) string {
        if url.contains('/abs/') {
                parts := url.split('/abs/')
                if parts.len > 1 {
                        id_part := parts[1].split('?')[0].split('#')[0]
                        return id_part
                }
        }
        return ''
}

fn extract_categories(subjects string) []string {
        mut cats := []string{}
        if subjects.len == 0 {
                return cats
        }
        parts := subjects.split(';')
        for part in parts {
                trimmed := part.trim_space()
                if trimmed.len > 0 {
                        cats << trimmed
                }
        }
        if cats.len == 0 {
                parts2 := subjects.split(',')
                for part in parts2 {
                        trimmed := part.trim_space()
                        if trimmed.len > 0 {
                                cats << trimmed
                        }
                }
        }
        return cats
}

fn count_words(text string) int {
        words := text.split_any(' \n\t\r')
        mut count := 0
        for word in words {
                if word.trim_space().len > 0 {
                        count++
                }
        }
        return count
}

fn calculate_quality_score(content string, translated string) f64 {
        if content.len == 0 || translated.len == 0 {
                return 0.0
        }
        length_ratio := f64(translated.len) / f64(content.len)
        length_score := if length_ratio >= 0.7 && length_ratio <= 1.5 { 1.0 } else if length_ratio >= 0.5 && length_ratio <= 2.0 { 0.8 } else if length_ratio >= 0.3 && length_ratio <= 3.0 { 0.5 } else { 0.2 }
        scientific_words := ['theorem', 'hypothesis', 'analysis', 'algorithm', 'quantum', 'neural', 'proof', 'equation', 'matrix', 'function', 'model', 'theory', 'research', 'study', 'method', 'result', 'conclusion', 'abstract', 'arxiv', 'paper', 'experiment', 'data', 'variable', 'parameter', 'optimization', 'convergence', 'distribution', 'probability', 'statistics', 'inference']
        mut science_count := 0
        content_lower := content.to_lower()
        for word in scientific_words {
                if content_lower.contains(word) {
                        science_count++
                }
        }
        science_score := if science_count >= 8 { 1.0 } else if science_count >= 5 { 0.85 } else if science_count >= 3 { 0.7 } else if science_count >= 1 { 0.5 } else { 0.2 }
        has_math := content.contains('\\') || content.contains('$') || content.contains('^') || content.contains('_') || content.contains('∫') || content.contains('∑') || content.contains('∏')
        math_score := if has_math { 1.0 } else { 0.6 }
        has_structure := content.contains('Abstract:') || content.contains('Title:') || content.contains('Authors:')
        structure_score := if has_structure { 1.0 } else { 0.5 }
        translated_lower := translated.to_lower()
        mut hungarian_indicators := 0
        hungarian_words := ['tétel', 'hipotézis', 'elemzés', 'algoritmus', 'kvantum', 'neurális', 'bizonyítás', 'egyenlet', 'mátrix', 'függvény', 'modell', 'elmélet', 'kutatás', 'tanulmány', 'módszer', 'eredmény', 'következtetés', 'összefoglaló', 'cikk', 'kísérlet', 'adat', 'változó', 'paraméter', 'optimalizálás', 'konvergencia', 'eloszlás', 'valószínűség', 'statisztika', 'következtetés']
        for word in hungarian_words {
                if translated_lower.contains(word) {
                        hungarian_indicators++
                }
        }
        translation_quality := if hungarian_indicators >= 5 { 1.0 } else if hungarian_indicators >= 3 { 0.85 } else if hungarian_indicators >= 1 { 0.7 } else { 0.4 }
        content_words := count_words(content)
        translated_words := count_words(translated)
        word_ratio := if content_words > 0 { f64(translated_words) / f64(content_words) } else { 0.0 }
        word_score := if word_ratio >= 0.6 && word_ratio <= 1.4 { 1.0 } else if word_ratio >= 0.4 && word_ratio <= 2.0 { 0.7 } else { 0.4 }
        final_score := (length_score * 0.20) + (science_score * 0.20) + (math_score * 0.15) + (structure_score * 0.10) + (translation_quality * 0.25) + (word_score * 0.10)
        return final_score
}

fn estimate_token_count(text string) int {
        base_estimate := text.len / 4
        word_count := count_words(text)
        word_based := word_count * 1.3
        final_estimate := int((f64(base_estimate) + word_based) / 2.0)
        if final_estimate < 50 {
                return 50
        }
        return final_estimate + 200
}

fn translate_with_cerebras(content string, model ModelConfig, mut rate_limiter RateLimiter) !(string, i64, int) {
        start_time := time.now().unix_milli()
        estimated_tokens := estimate_token_count(content) * 2
        rate_limiter.check_and_wait(estimated_tokens)!
        mut chunks := []string{}
        usable_context := model.max_context - 1000
        if content.len > usable_context {
                chunk_size := usable_context
                for i := 0; i < content.len; i += chunk_size {
                        end := if i + chunk_size < content.len { i + chunk_size } else { content.len }
                        chunks << content[i..end]
                }
        } else {
                chunks << content
        }
        mut full_translation := strings.new_builder(content.len * 2)
        mut total_tokens := 0
        for chunk_idx, chunk in chunks {
                request := CompletionRequest{
                        model: model.name
                        messages: [
                                Message{
                                        role: 'system'
                                        content: 'You are a world-class scientific translator, translating scientific articles from English to Hungarian. Your task is: 1) Preserve scientific terminology accurately. 2) Keep mathematical notations, LaTeX code, and equations unchanged. 3) The translation should be natural in Hungarian, but professionally correct and precise. 4) Do not add anything or offer opinions, just translate the text. 5) Maintain paragraphs and formatting.'
                                }
                                Message{
                                        role: 'user'
                                        content: chunk
                                }
                        ]
                        stream: true
                        max_completion_tokens: model.max_output
                        temperature: model.temperature
                        top_p: model.top_p
                }
                json_body := json.encode(request)
                mut req := http.new_request(http.Method.post, cerebras_api_url, json_body)
                req.add_header(http.CommonHeader.authorization, 'Bearer ${cerebras_api_key}')
                req.add_header(http.CommonHeader.content_type, 'application/json')
                req.add_header(http.CommonHeader.accept, 'text/event-stream')
                resp := req.do()!
                if resp.status_code == 429 {
                        time.sleep(70 * time.second)
                        return translate_with_cerebras(content, model, mut rate_limiter)!
                }
                if resp.status_code == 503 || resp.status_code == 502 {
                        time.sleep(5 * time.second)
                        return translate_with_cerebras(content, model, mut rate_limiter)!
                }
                if resp.status_code != 200 {
                        return error('API error ${resp.status_code}: ${resp.body}')
                }
                lines := resp.body.split('\n')
                for line in lines {
                        if line.starts_with('data: ') {
                                data := line[6..].trim_space()
                                if data.contains('[DONE]') {
                                        break
                                }
                                if data.len < 10 {
                                        continue
                                }
                                chunk_data := json.decode<StreamChunk>(data) or { continue }
                                if chunk_data.choices.len > 0 {
                                        delta_content := chunk_data.choices[0].delta.content
                                        if delta_content.len > 0 {
                                                full_translation.write_string(delta_content)
                                        }
                                }
                        }
                }
                if chunk_idx < chunks.len - 1 {
                        full_translation.write_string('\n\n')
                }
        }
        translated_text := full_translation.str()
        total_tokens = estimate_token_count(translated_text)
        processing_time := time.now().unix_milli() - start_time
        return translated_text, processing_time, total_tokens
}

struct ScrapeTask {
        url string
        depth int
}

fn scrape_url(url string) !string {
        mut req := http.new_request(http.Method.get, url, '')
        req.add_header(http.CommonHeader.user_agent, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36')
        req.add_header(http.CommonHeader.accept, 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8')
        req.add_header(http.CommonHeader.accept_language, 'en-US,en;q=0.9')
        req.add_header(http.CommonHeader.accept_encoding, 'gzip, deflate, br')
        req.add_header(http.CommonHeader.connection, 'keep-alive')
        resp := req.do()!
        if resp.status_code == 429 {
                time.sleep(15 * time.second)
                return scrape_url(url)!
        }
        if resp.status_code == 503 || resp.status_code == 502 {
                time.sleep(5 * time.second)
                return scrape_url(url)!
        }
        if resp.status_code != 200 {
                return error('HTTP ${resp.status_code}')
        }
        return resp.body
}

fn extract_arxiv_links(html string, base_url string) []string {
        mut links := []string{}
        mut i := 0
        for i < html.len {
                href_idx := html.index_after('href="', i)
                if href_idx == -1 {
                        break
                }
                start := href_idx + 6
                end_idx := html.index_after('"', start)
                if end_idx == -1 {
                        break
                }
                link := html[start..end_idx]
                if link.starts_with('/abs/') || link.starts_with('/pdf/') || link.starts_with('/list/') || link.starts_with('/archive/') || link.starts_with('/search/') {
                        full_url := if link.starts_with('http') { link } else { base_url + link }
                        if !full_url.contains('.pdf') && !links.contains(full_url) {
                                links << full_url
                        }
                }
                i = end_idx + 1
        }
        return links
}

struct Worker {
        id int
mut:
        rate_limiters []&RateLimiter
        models []ModelConfig
        current_model_idx int
}

fn (mut w Worker) get_next_model() (ModelConfig, &RateLimiter) {
        model := w.models[w.current_model_idx]
        limiter := w.rate_limiters[w.current_model_idx]
        w.current_model_idx = (w.current_model_idx + 1) % w.models.len
        return model, limiter
}

fn (mut w Worker) process_task(task ScrapeTask, result_ch chan JAIDETrainingExample) {
        html := scrape_url(task.url) or {
                return
        }
        content := extract_scientific_content(html)
        if content.len < 200 {
                return
        }
        model, mut limiter := w.get_next_model()
        translated, proc_time, token_count := translate_with_cerebras(content, model, mut limiter) or {
                return
        }
        if translated.len < 50 {
                return
        }
        quality := calculate_quality_score(content, translated)
        if quality < quality_threshold {
                return
        }
        arxiv_id := extract_arxiv_id(task.url)
        subjects := extract_between(html, '<td class="tablecell subjects">', '</td>')
        categories := extract_categories(clean_html_tags(subjects))
        has_math := content.contains('\\') || content.contains('$') || content.contains('^') || content.contains('_') || content.contains('∫') || content.contains('∑')
        has_code := content.contains('```
        word_count := count_words(content)
        example := JAIDETrainingExample{
                instruction: 'Translate the following scientific article excerpt to Hungarian. Preserve scientific terminology accurately, keep mathematical notations and LaTeX code unchanged. The translation should be natural in Hungarian, but professionally correct and precise.'
                input: content
                output: translated
                metadata: JAIDEMetadata{
                        source_url: task.url
