}

fn main() {
        models := get_models()
        mut rate_limiters := []&RateLimiter{}
        for model in models {
                rate_limiters << new_rate_limiter(model.name, model)
        }
        task_ch := chan ScrapeTask{cap: max_concurrent_tasks}
        result_ch := chan JAIDETrainingExample{cap: max_concurrent_tasks}
        mut visited := map[string]bool{}
        mut visited_lock := sync.new_mutex()
        mut workers := []Worker{}
        for i in 0 .. worker_count {
                workers << Worker{
                        id: i
                        rate_limiters: rate_limiters
                        models: models
                        current_model_idx: i % models.len
                }
        }
        for mut worker in workers {
                go fn [mut worker, task_ch, result_ch] () {
                        for {
                                task := <-task_ch or { break }
                                worker.process_task(task, result_ch)
                        }
                }()
        }
        mut examples_saved := 0
        mut file_lock := sync.new_mutex()
        go fn [result_ch, mut examples_saved, mut file_lock] () {
                mut file := os.create(output_file) or {
                        return
                }
                defer { file.close() }
                for {
                        example := <-result_ch or { break }
                        json_line := json.encode(example)
                        file_lock.@lock()
                        file.writeln(json_line) or {
                                file_lock.unlock()
                                continue
                        }
                        examples_saved++
                        file_lock.unlock()
                }
        }()
        mut queue := [ScrapeTask{url: base_url, depth: 0}]
        mut processed := 0
        for queue.len > 0 && processed < max_pages {
                task := queue
                queue = queue[1..]
                visited_lock.@lock()
                if task.url in visited {
                        visited_lock.unlock()
                        continue
                }
                visited[task.url] = true
                visited_lock.unlock()
                if task.depth < max_depth {
                        html := scrape_url(task.url) or {
