                        }
                        new_links := extract_arxiv_links(html, base_url)
                        for link in new_links {
                                visited_lock.@lock()
                                is_visited := link in visited
                                visited_lock.unlock()
                                if !is_visited && queue.len < 50000 {
                                        queue << ScrapeTask{url: link, depth: task.depth + 1}
                                }
                        }
                }
                task_ch <- task
                processed++
                time.sleep(request_delay_ms * time.millisecond)
        }
        task_ch.close()
        time.sleep(30 * time.second)
        result_ch.close()
        time.sleep(10 * time.second)
}

